SELECT cs.canonical_smiles, md_sub.pref_name AS substrate_compound_name, md_par.pref_name AS parent_compound_name, met.met_conversion, met.pathway_key, met.organism, met.enzyme_name FROM metabolism met JOIN compound_records cr_sub ON met.substrate_record_id = cr_sub.record_id JOIN molecule_dictionary md_sub ON cr_sub.molregno = md_sub.molregno JOIN compound_structures cs ON md_sub.molregno = cs.molregno LEFT JOIN molecule_hierarchy mh ON md_sub.molregno = mh.molregno LEFT JOIN molecule_dictionary md_par ON mh.parent_molregno = md_par.molregno WHERE met.enzyme_name = 'UGT1A9' LIMIT 200
